package android.text; public class SpannableStringBuilder implements CharSequence { private final StringBuilder b=new StringBuilder(); public SpannableStringBuilder append(CharSequence s){b.append(s);return this;} public SpannableStringBuilder append(char c){b.append(c);return this;} public void setSpan(Object o,int start,int end,int flags){} public int length(){return b.length();} public char charAt(int i){return b.charAt(i);} public CharSequence subSequence(int s,int e){return b.subSequence(s,e);} public String toString(){return b.toString();} }
